{
  "facts": [
    {
      "topic": "scope",
      "statement": "The entry reads PNG bytes sequentially: it reads metadata, updates row information, allocates a row, selects interlace handling, reads rows for each returned pass, and reads the end record.",
      "evidence": [
        {
          "unit_id": "u-e9cdca141412a92154b2",
