          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied recipe disables STDIO, WARNING, and WRITE through pnglibconf.dfa, runs configure without arguments, builds libpng16.la, and links the read fuzzer against the static library and zlib.",
      "evidence": [
        {
          "unit_id": "u-d102cd4502b9fe57a4ec",
          "start_line": 25,
          "end_line": 43,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "trigger",
      "statement": "The PNG IHDR supplies the interlace type stored in png_ptr->interlaced. The harness calls png_read_update_info before png_set_interlace_handling and then loops over the pass count returned by the setter.",
      "evidence": [
        {
          "unit_id": "u-882b031ef1057ef43002",
          "start_line": 863,
          "end_line": 875,
          "role": "dependency",
          "dependency_reason": "The before-source IHDR parser assigns input interlace data to the state used by row initialization."
        },
        {
          "unit_id": "u-0d38d914697479a848a9",
          "start_line": 864,
          "end_line": 876,
          "role": "dependency",
          "dependency_reason": "The after-source IHDR parser assigns input interlace data to the state used by row initialization."
        },
        {
          "unit_id": "u-e9cdca141412a92154b2",
          "start_line": 139,
          "end_line": 175,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "In both versions, row initialization assigns an interlaced image height rows when PNG_INTERLACE is set; otherwise it assigns the first pass's row count using the Adam7 vertical increment. It marks row initialization complete at the end.",
      "evidence": [
        {
          "unit_id": "u-132e00404c49344df0e2",
          "start_line": 4392,
          "end_line": 4425,
          "role": "primary",
